public class DatasetUtilities_iterateDomainBounds_TriageGen2Test {

    @Mock
    private XYDataset mockDataset;

    @Mock
    private IntervalXYDataset mockIntervalDataset;

    public DatasetUtilities_iterateDomainBounds_TriageGen2Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, false);
    }

    @Test
    public void testIterateDomainBounds_IncludeInterval_WithIntervalDataset_Success() {
        // Setup: Mock IntervalXYDataset behavior
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);

        // X=10, Start=5, End=15
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(10.0);
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(5.0);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IncludeInterval_WithIntervalDataset_WithNaN() {
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(2);

        // Item 1: Valid values (20, 20, 20)
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(20.0);
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(20.0);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(20.0);

        // Item 2: NaN values
        when(mockIntervalDataset.getXValue(0, 1)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getStartXValue(0, 1)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getEndXValue(0, 1)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertEquals(20.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IncludeInterval_WithRegularDataset() {
        // If includeInterval is true but dataset is NOT IntervalXYDataset, it falls into 'else'
        when(mockDataset.getSeriesCount()).thenReturn(2); // series 0 and 1. Note: loop starts at series 1 in 'else'
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, true);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_ExcludeInterval() {
        // 'else' block: loop starts from series = 1
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_EmptyOrNaNOnly_ReturnsNull() {
        // Case where minimum remains POSITIVE_INFINITY and maximum remains NEGATIVE_INFINITY
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_IncludeInterval_EmptyDataset() {
        // Case where seriesCount is 0
        when(mockIntervalDataset.getSeriesCount()).thenReturn(0);
        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);
        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_RegularDataset_MultipleSeries() {
        // Testing the 'else' block with multiple series starting from index 1
        when(mockDataset.getSeriesCount()).thenReturn(3);

        // Series 1
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(1.0);

        // Series 2
        when(mockDataset.getItemCount(2)).thenReturn(1);
        when(mockDataset.getXValue(2, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }
}
